#!/usr/bin/env python3
"""R42 A8 · write the public ES/EN Home after legacy assembly."""
from __future__ import annotations
import argparse, html
from pathlib import Path
SOURCE=Path(__file__).resolve().parents[1]

def picker(en):
    if en:
        return '<section class="ig-audience" data-ig-audience-picker aria-labelledby="ig-audience-title"><p class="ig-audience-title" id="ig-audience-title">Content for…</p><div class="ig-audience-options"><button type="button" data-ig-audience-stage="children" aria-pressed="false">Children</button><button type="button" data-ig-audience-stage="teenagers" aria-pressed="false">Teenagers</button><button type="button" data-ig-audience-stage="adults" aria-pressed="false">Adults</button><button type="button" data-ig-audience-stage="any" aria-pressed="false">Any age</button></div><p class="ig-audience-note">No date of birth, diagnosis or account. Without a choice, high-sensitivity content stays safe by default. Current view: <span class="ig-audience-status" data-ig-audience-status>Safe by default</span>.</p></section>'
    return '<section class="ig-audience" data-ig-audience-picker aria-labelledby="ig-audience-title"><p class="ig-audience-title" id="ig-audience-title">Contenido para…</p><div class="ig-audience-options"><button type="button" data-ig-audience-stage="children" aria-pressed="false">Infancia</button><button type="button" data-ig-audience-stage="teenagers" aria-pressed="false">Adolescencia</button><button type="button" data-ig-audience-stage="adults" aria-pressed="false">Adultez</button><button type="button" data-ig-audience-stage="any" aria-pressed="false">Cualquier edad</button></div><p class="ig-audience-note">Sin fecha de nacimiento, diagnóstico ni cuenta. Si no eliges, el contenido de alta sensibilidad permanece protegido por defecto. Vista actual: <span class="ig-audience-status" data-ig-audience-status>Protección por defecto</span>.</p></section>'

def render(root,lang):
    en=lang=='en';prefix='/en/' if en else '/'
    title='Iris Green · Clear information and practical tools' if en else 'Iris Green · Información clara y herramientas prácticas'
    desc='Find clear information, practical resources and everyday tools without having to choose a diagnosis.' if en else 'Encuentra información clara, recursos prácticos y herramientas cotidianas sin tener que elegir un diagnóstico.'
    nav=[('/en/neurodiversity/conditions/' if en else '/es/neurodiversidad/condiciones/','Conditions' if en else 'Condiciones'),('/en/situations/' if en else '/es/situaciones/','Situations' if en else 'Situaciones'),('/en/everyday-life/' if en else '/es/biblioteca/','Everyday life' if en else 'Vida diaria'),('/es/recursos/','Resources' if en else 'Recursos')]
    areas=[
    ('/en/neurodiversity/conditions/' if en else '/es/neurodiversidad/condiciones/','Conditions' if en else 'Condiciones','Understand a condition, experience or identity.' if en else 'Entender una condición, experiencia o identidad.'),
    ('/en/situations/' if en else '/es/situaciones/','Situations' if en else 'Situaciones','Start from what is happening in everyday life.' if en else 'Empezar por lo que te está pasando en el día a día.'),
    ('/en/everyday-life/' if en else '/es/biblioteca/','Everyday life' if en else 'Vida diaria','Practical support for routines, work, study and relationships.' if en else 'Apoyos prácticos para rutinas, trabajo, estudios y relaciones.'),
    ('/es/investigacion/?lang=en' if en else '/es/investigacion/','Research' if en else 'Investigación','Read what a study does and does not show.' if en else 'Leer qué demuestra y qué no demuestra un estudio.'),
    ('/en/data/' if en else '/es/datos/','Data' if en else 'Datos','Figures with context, population and source.' if en else 'Cifras con contexto, población y fuente.'),
    ('/es/tramites/directorio/','Support directory' if en else 'Ayudas y trámites','Find official support and procedures.' if en else 'Encontrar apoyos oficiales y trámites.'),
    ('/es/recursos/','Resources and games' if en else 'Recursos y juegos','Visual tools, routines and activities.' if en else 'Herramientas visuales, rutinas y actividades.'),
    ('/en/interests/' if en else '/es/intereses/','Your interests' if en else 'Tus intereses','Explore topics at your own pace.' if en else 'Explorar temas a tu ritmo.'),
    ('/es/taller/','The workshop' if en else 'El taller','Create, practise and work on projects.' if en else 'Crear, practicar y trabajar en proyectos.'),
    ('/en/quiet-space/' if en else '/es/sitio-tranquilo/','Quiet space' if en else 'Rincón tranquilo','A lower-stimulation space when you need it.' if en else 'Un espacio con menos estímulos cuando lo necesites.')]
    nav_html=''.join(f'<a href="{u}">{html.escape(t)}</a>' for u,t in nav)
    areas_html=''.join(f'<a class="ig-home-area" href="{u}"><strong>{html.escape(t)}</strong><span>{html.escape(d)}</span></a>' for u,t,d in areas)
    sabik=(SOURCE/'sabik/iris-panel.html').read_text(encoding='utf-8')
    search_title='What are you looking for?' if en else '¿Qué estás buscando?';ph='For example: noise drains me' if en else 'Por ejemplo: el ruido me agota';search='Search' if en else 'Buscar';areas_title='Choose where to start' if en else 'Elige por dónde empezar';settings='Settings' if en else 'Ajustes';close='Close' if en else 'Cerrar'
    page=f'''<!doctype html><html lang="{lang}"><head><script src="/assets/preferencias-lectura.js"></script><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><meta name="description" content="{html.escape(desc)}"><link rel="canonical" href="https://irisgreen.eu{prefix}"><link rel="alternate" hreflang="es" href="https://irisgreen.eu/"><link rel="alternate" hreflang="en" href="https://irisgreen.eu/en/"><link rel="alternate" hreflang="x-default" href="https://irisgreen.eu/"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Newsreader:opsz,wght@6..72,400;6..72,500;6..72,600&family=Atkinson+Hyperlegible:wght@400;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/ig-r42-materials.css"><link rel="stylesheet" href="/assets/ig-audience.css"><link rel="stylesheet" href="/assets/home-r42-child-safe.css"><link rel="stylesheet" href="/sabik/iris-mount.css"><script src="/assets/ig-audience.js"></script><script defer src="/assets/buscador-comun.js"></script><script defer src="/assets/home-r42-child-safe.js"></script></head><body class="ig-home-r42" data-ig-materials="r42" data-ig-r42-family="home"><a class="ig-home-skip" href="#main">{'Skip to content' if en else 'Ir al contenido'}</a><header class="ig-home-header"><a class="ig-home-brand" href="{prefix}">Iris Green</a><nav class="ig-home-nav" aria-label="{'Explore' if en else 'Explorar'}">{nav_html}</nav><button class="ig-home-menu-button" type="button" data-ig-home-menu-button aria-expanded="false" aria-controls="ig-home-mobile-menu">{'Menu' if en else 'Menú'}</button><a class="ig-home-lang" href="{'/' if en else '/en/'}" lang="{'es' if en else 'en'}">{'ES' if en else 'EN'}</a><button type="button" data-ig-home-settings-open>{settings}</button><nav class="ig-home-mobile-menu" id="ig-home-mobile-menu" data-ig-home-menu hidden>{nav_html}</nav></header><main id="main" class="ig-home-layout"><div class="ig-home-main"><section class="ig-home-hero"><p class="ig-home-eyebrow">{'Information and tools, without labels' if en else 'Información y herramientas, sin etiquetas'}</p><h1>{'Start with what you need.' if en else 'Empieza por lo que necesitas.'}</h1><p>{html.escape(desc)}</p>{picker(en)}</section><section class="ig-home-search-card"><h2>{search_title}</h2><form class="ig-home-search" data-ig-home-search role="search"><label class="ig-home-skip" for="ig-home-q">{search_title}</label><input id="ig-home-q" type="search" autocomplete="off" placeholder="{html.escape(ph)}"><button type="submit">{search}</button></form><div class="ig-home-suggestions" data-ig-home-suggestions></div><p class="ig-home-search-status" data-ig-home-search-status role="status" aria-live="polite"></p><div class="ig-home-results" data-ig-home-results></div></section><section class="ig-home-areas"><h2>{areas_title}</h2><div class="ig-home-area-grid">{areas_html}</div></section></div><aside class="ig-home-sabik-wrap" aria-label="Sabik"><h2>{'Ask Sabik' if en else 'Pregunta a Sabik'}</h2>{sabik}</aside></main><footer class="ig-home-footer"><span>Iris Green</span><nav><a href="{'/en/privacy/' if en else '/es/privacidad/'}">{'Privacy' if en else 'Privacidad'}</a><a href="/es/lectura-accesible/">{'Accessibility and reading' if en else 'Accesibilidad y lectura'}</a><a href="/es/sobre-iris-green/">{'About Iris Green' if en else 'Sobre Iris Green'}</a></nav></footer><nav class="ig-home-mobile-dock" aria-label="{'Quick access' if en else 'Accesos rápidos'}"><a href="{prefix}">{'Home' if en else 'Inicio'}</a><a href="{'/en/situations/' if en else '/es/situaciones/'}">{'Situations' if en else 'Situaciones'}</a><a href="/es/recursos/">{'Resources' if en else 'Recursos'}</a><button type="button" data-ig-home-settings-open>{settings}</button></nav><dialog id="ig-home-settings"><div class="ig-home-settings-head"><h2>{settings}</h2><button type="button" data-ig-home-settings-close aria-label="{close}">×</button></div><p>{'Choose the amount of transparency used in bars and menus. Your content and work stay unchanged.' if en else 'Elige cuánta transparencia usan las barras y los menús. El contenido y tu trabajo no cambian.'}</p><div data-ig-reading-panel id="ig-reading-panel"></div><p><a href="/es/lectura-accesible/">{'Open all reading and accessibility settings' if en else 'Abrir todos los ajustes de lectura y accesibilidad'}</a></p></dialog><script defer src="/sabik/sabik-motion-r37.js"></script><script defer src="/sabik/sabik-web-r01.js"></script><script defer src="/sabik/retrieval-panel.js"></script><script type="module" src="/sabik/iris-mount.mjs"></script></body></html>'''
    out=root if not en else root/'en';out.mkdir(parents=True,exist_ok=True);(out/'index.html').write_text(page,encoding='utf-8')
def sitemap(root):
    for name in ('sitemap.xml','sitemap-1.xml'):
        p=root/name
        if p.is_file():
            s=p.read_text(encoding='utf-8')
            if '<loc>https://irisgreen.eu/en/</loc>' not in s:s=s.replace('</urlset>','  <url>\n    <loc>https://irisgreen.eu/en/</loc>\n  </url>\n</urlset>')
            p.write_text(s,encoding='utf-8')
def main():
    ap=argparse.ArgumentParser();ap.add_argument('--root',type=Path,required=True);root=ap.parse_args().root.resolve();render(root,'es');render(root,'en');sitemap(root);print('R42 Home ES/EN written')
if __name__=='__main__':main()
